package com.wanyuecity.energy.system.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.wanyuecity.energy.core.BizException;import com.wanyuecity.energy.stall.entity.StallEngineeringAirConditioner;import com.wanyuecity.energy.stall.mapper.StallEngineeringAirConditionerMapper;import com.wanyuecity.energy.system.entity.AirConditionerSpecification;import com.wanyuecity.energy.system.mapper.AirConditionerSpecificationMapper;import com.wanyuecity.energy.system.service.dto.AirConditionerSpecificationRequest;import lombok.RequiredArgsConstructor;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;import java.util.Set;
@Service @RequiredArgsConstructor public class AirConditionerSpecificationService {
 private static final Set<String> TYPES=Set.of("FAN_COIL","HANGING_CABINET","OTHER");private final AirConditionerSpecificationMapper mapper;private final StallEngineeringAirConditionerMapper usageMapper;
 public List<AirConditionerSpecification> list(boolean enabledOnly){var q=new LambdaQueryWrapper<AirConditionerSpecification>();if(enabledOnly)q.eq(AirConditionerSpecification::getStatus,1);return mapper.selectList(q.orderByAsc(AirConditionerSpecification::getSortOrder).orderByAsc(AirConditionerSpecification::getId));}
 @Transactional public AirConditionerSpecification create(AirConditionerSpecificationRequest r){validate(r,null);var row=new AirConditionerSpecification();apply(row,r);mapper.insert(row);return row;}
 @Transactional public AirConditionerSpecification update(Long id,AirConditionerSpecificationRequest r){var row=require(id);validate(r,id);apply(row,r);mapper.updateById(row);return row;}
 @Transactional public void delete(Long id){require(id);if(usageMapper.selectCount(new LambdaQueryWrapper<StallEngineeringAirConditioner>().eq(StallEngineeringAirConditioner::getAirConditionerSpecificationId,id))>0)throw BizException.badRequest("该空调型号已被铺位使用，请停用而不要删除");mapper.deleteById(id);}
 public AirConditionerSpecification requireEnabled(Long id){var row=require(id);if(!Integer.valueOf(1).equals(row.getStatus()))throw BizException.badRequest("所选空调型号已停用");return row;}
 private AirConditionerSpecification require(Long id){var row=mapper.selectById(id);if(row==null)throw BizException.notFound("空调型号不存在");return row;}
 private void validate(AirConditionerSpecificationRequest r,Long id){if(!TYPES.contains(r.getEquipmentType()))throw BizException.badRequest("空调类型无效");long n=mapper.selectCount(new LambdaQueryWrapper<AirConditionerSpecification>().eq(AirConditionerSpecification::getSpecCode,r.getSpecCode().trim()).ne(id!=null,AirConditionerSpecification::getId,id));if(n>0)throw BizException.badRequest("空调规格编码不可重复");if(r.getStatus()!=null&&r.getStatus()!=0&&r.getStatus()!=1)throw BizException.badRequest("状态只能是启用或停用");}
 private void apply(AirConditionerSpecification row,AirConditionerSpecificationRequest r){BeanUtils.copyProperties(r,row);row.setSpecCode(r.getSpecCode().trim());row.setModel(r.getModel().trim());if(row.getStatus()==null)row.setStatus(1);if(row.getSortOrder()==null)row.setSortOrder(0);}
}
